#if LIE_C17_SAMPLING
std::shared_ptr<const JsonConstraint> JsonConstraint::CompileNative(
    const json::Value& schema, bool strict, bool object_only) {
  lie_gufo::NativeSchemaFrontend compiled;
  compiled.compile(schema, strict, object_only);
  auto grammar = std::shared_ptr<JsonConstraint>(new JsonConstraint());
  grammar->root_ = compiled.root();
  grammar->c17_program_ = compiled.take_program();
  grammar->prompt_ = compiled.take_prompt();
  grammar->lexemes_ = compiled.take_lexemes();
  return grammar;
}
#endif

std::shared_ptr<const JsonConstraint> JsonConstraint::Compile(

#if LIE_C17_SAMPLING
    return CompileNative(schema, false, true);
#else
    return JsonConstraintCompiler(schema, false).Compile(true);
#endif
